query hentPersoninfo($behandlingID: Long!) {
  hentSaksopplysninger(behandlingID: $behandlingID) {
    persondata {
      folkeregisterpersonstatuser {
        kode
        tekst
        master
        kilde
        fregGyldighetstidspunkt
        erHistorisk
        __typename
      }
      foedsel {
        foedeland
        foedested
        foedselsaar
        foedselsdato
        __typename
      }
      sivilstand {
        type
        relatertVedSivilstand
        gyldigFraOgMed
        bekreftelsesdato
        master
        kilde
        erHistorisk
        __typename
      }
      __typename
    }
    __typename
  }
}

query hentPersonopplysninger($behandlingID: Long!) {
  hentSaksopplysninger(behandlingID: $behandlingID) {
    persondata {
      navn {
        fornavn
        mellomnavn
        etternavn
        __typename
      }
      kjoenn
      folkeregisterpersonstatuser {
        kode
        erHistorisk
        __typename
      }
      folkeregisteridentifikator
      statsborgerskap {
        land
        erHistorisk
        __typename
      }
      sivilstand {
        type
        erHistorisk
        __typename
      }
      __typename
    }
    __typename
  }
}

